package pe.edu.upeu.casaonada.notificacion.api;
import pe.edu.upeu.casaonada.notificacion.dto.*; import pe.edu.upeu.casaonada.notificacion.service.NotificacionService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.net.URI; import java.util.*;
@RestController @RequestMapping("/api/v1/notificaciones") public class NotificacionController { private final NotificacionService s; public NotificacionController(NotificacionService s){this.s=s;} @PostMapping public ResponseEntity<NotificacionResponse> crear(@Valid @RequestBody NotificacionRequest r){var x=s.crear(r);return ResponseEntity.created(URI.create("/api/v1/notificaciones/"+x.id())).body(x);} @GetMapping public List<NotificacionResponse> listar(){return s.listar();} @GetMapping("/{id}") public NotificacionResponse buscar(@PathVariable Long id){return s.buscar(id);} @PostMapping("/{id}/leer") public NotificacionResponse leer(@PathVariable Long id){return s.marcarLeida(id);} }
